"""All source identities; analytic and discrete resampling channels stay separate."""
from crop import *
def main():
    frozen=load(R/'config/BEFORE_FORMAL_CALCULATION.json');assert sha(R/'config/GATE_A_PREREGISTERED.json')==frozen['protocol']['sha256'];save('config/CROP_EXECUTION_CODE.json',dict(code=[asset(p)for p in sorted((R/'code').glob('*.py'))],protocol=asset(R/'config/GATE_A_PREREGISTERED.json')))
    cfg=config();out=R/'local_results/crops';out.mkdir(exist_ok=True);rows=[];manifest=[]
    gate=REPO/'experiments/TASK-CAMERA-GATE-G01-004-PILOT-001/CAMERA_QUALIFICATION.csv';qual={r['camera']:r for r in csv.DictReader(gate.open())};blocks={r['source_id']:r['view_block']for r in csv.DictReader((D0/'VIEW_COVERAGE_SELECTION.csv').open())}
    for cid in IDS:
        s=native(cid);c=make_crop(s);uv=s['native_uv'];ids=s['native_id'];z=s['depth'][uv[:,1],uv[:,0]].astype(float);X=s['X'];q=affine_uv(uv,c['A']);Xa=unproject(z,s['T'],q,c['K_crop']);analytic=np.linalg.norm(X-Xa,axis=1)
        represented=np.unique(c['source_ids'][c['valid']]);represented_mask=np.isin(ids,represented);crop_out=(q[:,0]<-.5)|(q[:,0]>=319.5)|(q[:,1]<-.5)|(q[:,1]>=239.5);assert not crop_out.any(),'ROI_LOST_ORIGINAL_POLYP'
        qr=np.floor(q+.5).astype(int);inside=(qr[:,0]>=0)&(qr[:,0]<320)&(qr[:,1]>=0)&(qr[:,1]<240);resampled=np.zeros(len(q),bool);picked=np.full(len(q),-1,np.int64);err=np.full(len(q),np.nan);target_depth=np.full(len(q),np.nan);j=np.flatnonzero(inside);p=qr[j];good=c['valid'][p[:,1],p[:,0]];j=j[good];p=qr[j];resampled[j]=True;picked[j]=c['source_ids'][p[:,1],p[:,0]];target_depth[j]=c['depth_mm'][p[:,1],p[:,0]];Xr=unproject(target_depth[j],s['T'],p,c['K_crop']);err[j]=np.linalg.norm(Xr-X[j],axis=1)
        origCAD,_=cast(ringscene(),uv,s['Kn'],s['T']);analyticCAD,_=cast(ringscene(),q,c['K_crop'],s['T']);hidden0=np.isfinite(origCAD)&(z>origCAD+.002);hiddenA=np.isfinite(analyticCAD)&(z>analyticCAD+.002);discreteCAD,_=cast(ringscene(),qr[j],c['K_crop'],s['T']);hiddenR=np.isfinite(discreteCAD)&(target_depth[j]>discreteCAD+.002)
        dt,ridge=ridge_proxy(s['valid']);dtp,ridgep=ridge_proxy(c['valid']);native_width=2*dt[uv[:,1],uv[:,0]];isridge=ridge[uv[:,1],uv[:,0]];thin_theory=isridge&(native_width*c['scale']<3);thin_output=ridgep&(2*dtp<3)
        # Transparent geometric strata, not certified anatomy or hand-selected pixels.
        boundary=dt[uv[:,1],uv[:,0]]<=2;ringdist=cv2.distanceTransform((s['native_labels']!=2).astype(np.uint8),cv2.DIST_L2,5);ringnear=ringdist[uv[:,1],uv[:,0]]<=8
        dz=np.zeros(s['depth'].shape,float)
        for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
            nb=np.roll(s['depth'],(dy,dx),(0,1));nv=np.roll(s['valid'],(dy,dx),(0,1));ok=s['valid']&nv;delta=np.where(ok,abs(s['depth']-nb),0);dz=np.maximum(dz,delta)
        jump=dz[uv[:,1],uv[:,0]]>.25;head=dt[uv[:,1],uv[:,0]]>=np.quantile(dt[s['valid']],.75);stalk=isridge&(native_width<=6)
        footprint_x=c['depth_mm'][c['valid']]/c['K_crop'][0,0];footprint_y=c['depth_mm'][c['valid']]/c['K_crop'][1,1]
        row=dict(source=cid,original_legal_N=len(ids),crop_legal_output_N=int(c['valid'].sum()),represented_original_ID_N=len(represented),original_ID_not_represented_N=int((~represented_mask).sum()),original_ID_retention=float(represented_mask.mean()),outside_ROI_N=int(crop_out.sum()),analytic_XYZ_median_mm=float(np.median(analytic)),analytic_XYZ_p95_mm=float(np.quantile(analytic,.95)),analytic_XYZ_max_mm=float(analytic.max()),analytic_gate_pass=bool(analytic.max()<=cfg['thresholds']['analytic_XYZ_max_mm']),nearest_paired_eligible_N=int(resampled.sum()),nearest_ID_changed_N=int((resampled&(picked!=ids)).sum()),nearest_XYZ_median_mm=stats(err)['median'],nearest_XYZ_p95_mm=stats(err)['p95'],nearest_XYZ_max_mm=stats(err)['maximum'],nearest_unavailable_N=int((~resampled).sum()),scale=c['scale'],physical_footprint_x_median_mm=float(np.median(footprint_x)),physical_footprint_x_p95_mm=float(np.quantile(footprint_x,.95)),physical_footprint_y_median_mm=float(np.median(footprint_y)),physical_footprint_y_p95_mm=float(np.quantile(footprint_y,.95)),native_boundary_N=int(boundary.sum()),Ring_neighbour_N=int(ringnear.sum()),depth_jump_N=int(jump.sum()),head_proxy_N=int(head.sum()),stalk_proxy_N=int(stalk.sum()),thin_native_predicted_candidate_N=int(thin_theory.sum()),thin_crop_ridge_candidate_N=int(thin_output.sum()),minimum_crop_ridge_width_px=float((2*dtp[ridgep]).min()),thin_status='THIN_STRUCTURE_UNRESOLVED_BY_CROP'if thin_theory.any()or thin_output.any()else 'NO_SUB3PX_RIDGE_PROXY',Ring_depth_included_N=int((c['depth_mm'][c['labels']==2]>0).sum()),background_depth_included_N=int((c['depth_mm'][c['labels']==0]>0).sum()),padding_depth_included_N=int((c['depth_mm'][c['semantics']==4]>0).sum()),padding_output_N=int((c['semantics']==4).sum()),analytic_CAD_order_change_N=int((hidden0!=hiddenA).sum()),nearest_CAD_order_change_N=int((hidden0[j]!=hiddenR).sum()),nearest_CAD_evaluated_N=len(j),source_camera_status=qual.get(cid,{}).get('new_status','NOT_IN_CAMERA_GATE_PILOT_CONDITIONAL'))
        rows.append(row)
        np.savez_compressed(out/(cid+'.npz'),**{k:v for k,v in c.items()if isinstance(v,np.ndarray)})
        np.savez_compressed(out/(cid+'_identities.npz'),native_id=ids,native_uv=uv,original_X_mm=X,analytic_crop_uv=q,analytic_X_mm=Xa,analytic_error_mm=analytic,represented=represented_mask,nearest_output_uv=qr,nearest_source_id=picked,nearest_XYZ_error_mm=err,head_proxy=head,Mask_boundary=boundary,Ring_neighbour=ringnear,stalk_proxy=stalk,depth_jump=jump,thin_native_predicted=thin_theory,original_CAD_hidden=hidden0,analytic_CAD_hidden=hiddenA)
        src=next(r for r in MANIFEST['sources']if r['source_id']==cid);manifest.append(dict(source_id=cid,order=IDS.index(cid)+1,block=blocks[cid],role='CORE'if cid in CORE else 'CONDITIONAL_BRIDGE'if cid.endswith('r04')else 'CONDITIONAL_NEW_DIRECTION',historical_camera_qualification=qual.get(cid,{}).get('new_status','NOT_IN_CAMERA_GATE_PILOT'),historical_qualification_unchanged=True,original_size_native_WH=[640,352],archived_WH=[640,360],output_WH=[320,240],source_bbox_native=c['source_bbox'],expanded_bbox_native=c['expanded_bbox'],crop_bbox_native=c['crop_bbox'],scale=c['scale'],padding_native=c['padding_native'],letterbox_output_px=c['letterbox_output_px'],A=c['A'],A_inverse=c['A_inverse'],K_native=s['Kn'],K_archived=s['K'],K_crop=c['K_crop'],c2w_mm=s['T'],crop_summary=row,original_assets=src['assets'],HERO_upstream_RGB=src['HERO_upstream_RGB'],output_semantics=dict(BG=0,LEGAL_POLYP=1,RING=2,UNKNOWN_POLYP=3,PADDING=4),local_crop=asset(out/(cid+'.npz')),identity_evidence=asset(out/(cid+'_identities.npz'))))
        print('CROP',cid,'a',c['scale'],'analytic_max',analytic.max(),'retained',represented_mask.mean(),'thin',row['thin_status'],flush=True)
    ref=rows[0]
    for r in rows:r['physical_footprint_x_ratio_to_ref08']=r['physical_footprint_x_median_mm']/ref['physical_footprint_x_median_mm'];r['physical_footprint_y_ratio_to_ref08']=r['physical_footprint_y_median_mm']/ref['physical_footprint_y_median_mm']
    table('CROP_GEOMETRY_TESTS.csv',rows);save('SOURCE_AND_CROP_MANIFEST.json',dict(task=R.name,protocol=asset(R/'config/GATE_A_PREREGISTERED.json'),sources=manifest,source_order=IDS,native_valid_total=sum(r['original_legal_N']for r in rows),no_manual_ROI_adjustments=True,camera_updates=0,GT=False))
    save('config/REUSED_FUNCTIONS.json',REUSE)
if __name__=='__main__':main()
